"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7383],{97383:a=>{a.exports=JSON.parse('{"slug":"rozhdaemost-rossiya-2025-demograficheskoe-eho","locale":"zh","title":"俄罗斯2025年约出生1.19百万儿童，少于1999年","description":"俄罗斯2025年出生约1.19百万，低于1999年。解释出生下降对工资、养老金和生育补助的意义。","blocks":[{"id":"b001","kind":"paragraph","text":"2025年俄罗斯约出生1.19百万儿童。Rosstat自2024年几乎不发布出生数据，只能按女性人数及各年龄生育率间接估算。人口学家阿列克谢\xb7拉克沙估1.18百万，相近。低于1999年的1.21百万。已连续下降10年：2015年1.94百万、2020年1.44百万、2023年1.26百万。"},{"id":"b002","kind":"paragraph","text":"出生数取决于2件事：每位女性平均生几个，以及育龄女性有多少。设想学校在1990年代末从招2个一年级班变为1个；25–30年后这些孩子成为父母，即便每家生育与上一代相同，一年级仍更少，这称人口回声。2024年15–49岁女性34.2百万，Rosstat预测2046年仅27.4百万，少近20%。"},{"id":"b003","kind":"paragraph","text":"第二原因是每位女性生育数，目前约1.36，与欧盟1.34、德国1.35相近。世代更替需约2.1；在1.36下，下一代约少三分之一（1.36 / 2.1 ≈ 0.65）。俄罗斯2024年家庭政策支出占GDP的1.3%，OECD均值略超2%。"},{"id":"b004","kind":"paragraph","text":"对家庭，卢布补助购买力下降。2016年第二胎生育资本453千卢布，可买约8.4平方米住房。2026年首次因第二胎领取约963千，是2.1倍，但房价约涨3.4倍，只够5.2平方米。第一胎约729千，只够4平方米。2026年十月1日起，有1个孩子的家庭房贷从6%变为10–12%。"},{"id":"b005","kind":"paragraph","text":"今天孩子少，20年后劳动者就少。经济学家罗斯季斯拉夫\xb7卡佩柳什尼科夫估2045年就业者少7百万，约每十人少一人，悲观情景少10.5百万。员工议价能力增强，人少则必须付更多工资。但每位退休者由更少劳动者支持，税基收缩。"},{"id":"b006","kind":"paragraph","text":"持未用生育资本证书的家庭面临现在用还是等。自2016年房价快于指数调整，等待每年都损失面积。资本按通胀调，只有房价不比通胀快，延期才买得起同样面积；未来房价无人能保证。"},{"id":"b007","kind":"heading","text":"俄罗斯2025年出生多少儿童？"},{"id":"b008","kind":"paragraph","text":"间接估约1.19百万，拉克沙估1.18百万，低于1999年1.21百万。Rosstat自2024年几乎不公开出生数，所以依据女性人数和年龄生育率估算。"},{"id":"b009","kind":"heading","text":"俄罗斯为何出生越来越少？"},{"id":"b010","kind":"paragraph","text":"2个原因叠加：每位女性约1.36个孩子，世代替代需约2.1；同时育龄女性本身更少，因为出生于人数较少的1990年代。"},{"id":"b011","kind":"heading","text":"2026年生育资本能买多少住房？"},{"id":"b012","kind":"paragraph","text":"第二胎首次领取约963千卢布，可买约5.2平方米；第一胎约729千，可买4平方米。2016年453千可买8.4平方米。金额涨2.1倍，房价约涨3.4倍。"}],"sources":[{"label":"人口危机回归：俄罗斯人口下降","url":"https://thebell.io/demograficheskiy-krizis-vernulsya-naselenie-rossii-sokrashchaetsya--i-delo-ne-tolko-v-voyne-no-i-v-sistemnom-nedofinansirovanii-semeynoy-politiki"},{"label":"2026年指数调整后生育资本金额","url":"https://www.rbc.ru/life/news/69ba3abc9a79474f38cf830b"}],"sourceBodySha256":"ff9748ccf2ba9fa76599dc66cba937d70782141706610d69e9984d278c697e19"}')}}]);